import type { Span, SpanCreate, SpanUpdate } from './model';
import { SpanRepository, SpanNotFoundError } from './repository';
import { validateSpanCreate, validateSpanUpdate } from './validator';

export interface SpanServiceDeps {
  repository: SpanRepository;
  clock?: () => Date;
  logger?: (msg: string, meta?: Record<string, unknown>) => void;
}

export interface ListSpanOptions {
  offset?: number;
  limit?: number;
  sortBy?: keyof Span;
  order?: 'asc' | 'desc';
}

/**
 * Business-logic layer above SpanRepository.
 */
export class SpanService {
  private readonly repo: SpanRepository;
  private readonly clock: () => Date;
  private readonly logger: (msg: string, meta?: Record<string, unknown>) => void;

  constructor(deps: SpanServiceDeps) {
    this.repo = deps.repository;
    this.clock = deps.clock ?? (() => new Date());
    this.logger = deps.logger ?? (() => { /* noop */ });
  }

  create(input: SpanCreate): Span {
    const errors = validateSpanCreate(input);
    if (errors.length > 0) throw new SpanValidationError(errors);
    const created = this.repo.insert(input);
    this.logger('SpanService.create', { id: created.id });
    return created;
  }

  get(id: string): Span {
    return this.repo.requireById(id);
  }

  tryGet(id: string): Span | undefined {
    return this.repo.findById(id);
  }

  update(id: string, patch: SpanUpdate): Span {
    const errors = validateSpanUpdate(patch);
    if (errors.length > 0) throw new SpanValidationError(errors);
    const updated = this.repo.update(id, patch);
    this.logger('SpanService.update', { id });
    return updated;
  }

  delete(id: string): void {
    const existed = this.repo.delete(id);
    if (!existed) throw new SpanNotFoundError(id);
    this.logger('SpanService.delete', { id });
  }

  list(options: ListSpanOptions = {}): Span[] {
    const offset = options.offset ?? 0;
    const limit = options.limit ?? 50;
    if (options.sortBy) {
      const sorted = this.repo.sortedBy(options.sortBy, options.order);
      return sorted.slice(offset, offset + limit);
    }
    return this.repo.paginate(offset, limit);
  }

  countAll(): number {
    return this.repo.count();
  }

  batchCreate(inputs: SpanCreate[]): Span[] {
    for (const input of inputs) {
      const errors = validateSpanCreate(input);
      if (errors.length > 0) throw new SpanValidationError(errors);
    }
    return this.repo.batchInsert(inputs);
  }

  exists(id: string): boolean {
    return this.repo.findById(id) !== undefined;
  }

  bulkDelete(ids: string[]): number {
    let deleted = 0;
    for (const id of ids) if (this.repo.delete(id)) deleted++;
    return deleted;
  }

  searchByField<K extends keyof Span>(field: K, value: Span[K]): Span[] {
    return this.repo.filter((entity) => entity[field] === value);
  }
}

export class SpanServiceError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SpanServiceError';
  }
}

export class SpanValidationError extends Error {
  constructor(public readonly errors: string[]) {
    super(`Span validation failed: ${errors.join('; ')}`);
    this.name = 'SpanValidationError';
  }
}
